-- =====================================================================================================
-- Cerebro — relational schema (PostgreSQL 15+)
--
-- The TypeScript domain model (src/domains/*/types) maps 1:1 onto these tables:
--   * Every table has a surrogate primary key `id BIGINT GENERATED BY DEFAULT AS IDENTITY`, i.e. its own
--     sequence. `EntityId` in the code is this value. Keys are never reused after deletes.
--   * Rows the UI edits as part of an aggregate (environments, milestones, role assignments…) are
--     child tables with their own sequence. Write requests send `id = NULL` for new child rows
--     (`Draft<T>` in the code) and the server assigns `nextval`.
--   * Many-to-many links (team members, decision makers, related applications/projects) are tables
--     with their own id plus a unique constraint on the pair.
--   * Enumerated values are rows of `master_data_items`. Records store the stable `code`; each
--     code column has a constant companion column so a composite foreign key can check the code
--     against the right list (`<column>_list`).
--   * Audit columns reference `people` (NULL when the acting account is not linked to a person).
--
-- The in-memory mock (src/services/mock) mirrors this: `database.ts` keeps one sequence per table
-- (`SEQUENCES`) and `WriteKit.nextId` / `withIds` hand out keys the way `nextval` would.
-- =====================================================================================================

-- -----------------------------------------------------------------------------------------------------
-- Master data
-- -----------------------------------------------------------------------------------------------------

CREATE TABLE master_data_items (
  id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  list_key     TEXT        NOT NULL,              -- MASTER_DATA_LIST_KEYS, e.g. 'applicationTypes'
  code         TEXT        NOT NULL CHECK (code ~ '^[A-Za-z0-9]+([-_][A-Za-z0-9]+)*$'),
  label        TEXT        NOT NULL,
  description  TEXT        NOT NULL DEFAULT '',
  variant      TEXT,                              -- badge colour, NULL for plain-text lists
  active       BOOLEAN     NOT NULL DEFAULT TRUE,
  sort_order   INTEGER     NOT NULL,              -- display order within the list
  UNIQUE (list_key, code),
  UNIQUE (list_key, label)
);

-- -----------------------------------------------------------------------------------------------------
-- Organisation
-- -----------------------------------------------------------------------------------------------------

CREATE TABLE business_units (
  id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code            TEXT NOT NULL UNIQUE,
  name            TEXT NOT NULL UNIQUE,
  description     TEXT NOT NULL DEFAULT '',
  head_person_id  BIGINT                          -- FK added below (people ↔ business_units cycle)
);

CREATE TABLE people (
  id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  full_name         TEXT NOT NULL,
  job_title         TEXT NOT NULL,
  email             TEXT NOT NULL UNIQUE,
  business_unit_id  BIGINT REFERENCES business_units (id) ON DELETE SET NULL,
  location          TEXT
);

ALTER TABLE business_units
  ADD FOREIGN KEY (head_person_id) REFERENCES people (id) ON DELETE RESTRICT;

CREATE TABLE user_accounts (
  id                      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  display_name            TEXT        NOT NULL,
  email                   TEXT        NOT NULL UNIQUE,
  role                    TEXT        NOT NULL CHECK (role IN ('admin', 'user')),
  person_id               BIGINT      REFERENCES people (id) ON DELETE RESTRICT,
  active                  BOOLEAN     NOT NULL DEFAULT TRUE,
  last_sign_in_at         TIMESTAMPTZ,
  created_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by_person_id    BIGINT      REFERENCES people (id),
  updated_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by_person_id    BIGINT      REFERENCES people (id),
  last_reviewed_at        TIMESTAMPTZ,
  last_reviewed_by_person_id BIGINT   REFERENCES people (id)
);

CREATE TABLE teams (
  id                      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name                    TEXT        NOT NULL UNIQUE,
  description             TEXT        NOT NULL DEFAULT '',
  manager_person_id       BIGINT      REFERENCES people (id) ON DELETE RESTRICT,
  contact_email           TEXT,
  chat_channel            TEXT,
  responsibilities        TEXT[]      NOT NULL DEFAULT '{}',
  created_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by_person_id    BIGINT      REFERENCES people (id),
  updated_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by_person_id    BIGINT      REFERENCES people (id),
  last_reviewed_at        TIMESTAMPTZ,
  last_reviewed_by_person_id BIGINT   REFERENCES people (id)
);

CREATE TABLE team_members (                       -- Team.memberIds
  id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  team_id    BIGINT NOT NULL REFERENCES teams (id) ON DELETE CASCADE,
  person_id  BIGINT NOT NULL REFERENCES people (id) ON DELETE RESTRICT,
  UNIQUE (team_id, person_id)
);

-- -----------------------------------------------------------------------------------------------------
-- Technology catalogue
-- -----------------------------------------------------------------------------------------------------

CREATE TABLE technologies (
  id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name           TEXT NOT NULL UNIQUE,
  description    TEXT NOT NULL DEFAULT '',
  category       TEXT NOT NULL,
  category_list  TEXT NOT NULL GENERATED ALWAYS AS ('technologyCategories') STORED,
  status         TEXT NOT NULL,
  status_list    TEXT NOT NULL GENERATED ALWAYS AS ('technologyStatuses') STORED,
  FOREIGN KEY (category_list, category) REFERENCES master_data_items (list_key, code),
  FOREIGN KEY (status_list, status) REFERENCES master_data_items (list_key, code)
);

-- -----------------------------------------------------------------------------------------------------
-- Applications
-- -----------------------------------------------------------------------------------------------------

CREATE TABLE applications (
  id                         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code                       TEXT        NOT NULL UNIQUE CHECK (code ~ '^[A-Z0-9-]+$'),
  name                       TEXT        NOT NULL,
  short_description          TEXT        NOT NULL,
  detailed_description       TEXT        NOT NULL DEFAULT '',
  business_purpose           TEXT        NOT NULL,
  type                       TEXT        NOT NULL,
  type_list                  TEXT        NOT NULL GENERATED ALWAYS AS ('applicationTypes') STORED,
  lifecycle                  TEXT        NOT NULL,
  lifecycle_list             TEXT        NOT NULL GENERATED ALWAYS AS ('applicationLifecycles') STORED,
  criticality                TEXT        NOT NULL,
  criticality_list           TEXT        NOT NULL GENERATED ALWAYS AS ('criticalities') STORED,
  operational_status         TEXT        NOT NULL,
  operational_status_list    TEXT        NOT NULL GENERATED ALWAYS AS ('operationalStatuses') STORED,
  tags                       TEXT[]      NOT NULL DEFAULT '{}',
  business_unit_id           BIGINT      REFERENCES business_units (id) ON DELETE RESTRICT,
  business_processes         TEXT[]      NOT NULL DEFAULT '{}',
  user_groups                TEXT[]      NOT NULL DEFAULT '{}',
  estimated_user_count       BIGINT      CHECK (estimated_user_count >= 0),
  hosting_model              TEXT        NOT NULL,
  hosting_model_list         TEXT        NOT NULL GENERATED ALWAYS AS ('hostingModels') STORED,
  cloud_provider             TEXT,
  hosting_notes              TEXT,
  created_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by_person_id       BIGINT      REFERENCES people (id),
  updated_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by_person_id       BIGINT      REFERENCES people (id),
  last_reviewed_at           TIMESTAMPTZ,
  last_reviewed_by_person_id BIGINT      REFERENCES people (id),
  FOREIGN KEY (type_list, type) REFERENCES master_data_items (list_key, code),
  FOREIGN KEY (lifecycle_list, lifecycle) REFERENCES master_data_items (list_key, code),
  FOREIGN KEY (criticality_list, criticality) REFERENCES master_data_items (list_key, code),
  FOREIGN KEY (operational_status_list, operational_status) REFERENCES master_data_items (list_key, code),
  FOREIGN KEY (hosting_model_list, hosting_model) REFERENCES master_data_items (list_key, code)
);

CREATE TABLE technology_usages (                  -- Application.technologies
  id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  application_id  BIGINT NOT NULL REFERENCES applications (id) ON DELETE CASCADE,
  technology_id   BIGINT NOT NULL REFERENCES technologies (id) ON DELETE RESTRICT,
  layer           TEXT   NOT NULL,
  layer_list      TEXT   NOT NULL GENERATED ALWAYS AS ('technologyCategories') STORED,
  version         TEXT,
  UNIQUE (application_id, technology_id, layer),
  FOREIGN KEY (layer_list, layer) REFERENCES master_data_items (list_key, code)
);

CREATE TABLE data_stores (                        -- Application.dataStores
  id                      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  application_id          BIGINT  NOT NULL REFERENCES applications (id) ON DELETE CASCADE,
  name                    TEXT    NOT NULL,
  technology_id           BIGINT  NOT NULL REFERENCES technologies (id) ON DELETE RESTRICT,
  purpose                 TEXT    NOT NULL DEFAULT '',
  contains_personal_data  BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE source_repositories (                -- Application.repositories
  id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  application_id  BIGINT NOT NULL REFERENCES applications (id) ON DELETE CASCADE,
  name            TEXT   NOT NULL,
  type            TEXT   NOT NULL,
  type_list       TEXT   NOT NULL GENERATED ALWAYS AS ('sourceRepositoryTypes') STORED,
  url             TEXT   NOT NULL CHECK (url ~ '^https?://'),
  default_branch  TEXT   NOT NULL,
  description     TEXT,
  FOREIGN KEY (type_list, type) REFERENCES master_data_items (list_key, code)
);

CREATE TABLE environments (                       -- Application.environments (never credentials)
  id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  application_id  BIGINT NOT NULL REFERENCES applications (id) ON DELETE CASCADE,
  type            TEXT   NOT NULL,
  type_list       TEXT   NOT NULL GENERATED ALWAYS AS ('environmentTypes') STORED,
  name            TEXT   NOT NULL,
  url             TEXT   CHECK (url IS NULL OR url ~ '^https?://'),
  status          TEXT   NOT NULL,
  status_list     TEXT   NOT NULL GENERATED ALWAYS AS ('environmentStatuses') STORED,
  region          TEXT,
  notes           TEXT,
  FOREIGN KEY (type_list, type) REFERENCES master_data_items (list_key, code),
  FOREIGN KEY (status_list, status) REFERENCES master_data_items (list_key, code)
);

-- -----------------------------------------------------------------------------------------------------
-- Projects
-- -----------------------------------------------------------------------------------------------------

CREATE TABLE projects (
  id                         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code                       TEXT          NOT NULL UNIQUE CHECK (code ~ '^[A-Z0-9-]+$'),
  name                       TEXT          NOT NULL,
  short_name                 TEXT          NOT NULL,
  description                TEXT          NOT NULL,
  objective                  TEXT          NOT NULL DEFAULT '',
  scope                      TEXT          NOT NULL DEFAULT '',
  out_of_scope               TEXT          NOT NULL DEFAULT '',
  type                       TEXT          NOT NULL,
  type_list                  TEXT          NOT NULL GENERATED ALWAYS AS ('projectTypes') STORED,
  priority                   TEXT          NOT NULL,
  priority_list              TEXT          NOT NULL GENERATED ALWAYS AS ('criticalities') STORED,
  status                     TEXT          NOT NULL,
  status_list                TEXT          NOT NULL GENERATED ALWAYS AS ('projectStatuses') STORED,
  health                     TEXT          NOT NULL,
  health_list                TEXT          NOT NULL GENERATED ALWAYS AS ('projectHealths') STORED,
  confidentiality            TEXT          NOT NULL,
  confidentiality_list       TEXT          NOT NULL GENERATED ALWAYS AS ('confidentialityLevels') STORED,
  tags                       TEXT[]        NOT NULL DEFAULT '{}',
  business_unit_id           BIGINT        REFERENCES business_units (id) ON DELETE RESTRICT,
  planned_start_date         DATE,
  actual_start_date          DATE,
  planned_end_date           DATE          CHECK (planned_end_date IS NULL OR planned_start_date IS NULL OR planned_end_date >= planned_start_date),
  actual_end_date            DATE          CHECK (actual_end_date IS NULL OR actual_start_date IS NULL OR actual_end_date >= actual_start_date),
  progress_percentage        SMALLINT      NOT NULL CHECK (progress_percentage BETWEEN 0 AND 100),
  current_phase              TEXT          NOT NULL,
  current_phase_list         TEXT          NOT NULL GENERATED ALWAYS AS ('projectPhases') STORED,
  latest_status_summary      TEXT          NOT NULL DEFAULT '',
  next_steps                 TEXT          NOT NULL DEFAULT '',
  -- Project.financials (NULL currency = no financial information recorded)
  currency                   TEXT,
  currency_list              TEXT          NOT NULL GENERATED ALWAYS AS ('currencies') STORED,
  budget                     NUMERIC(18,2),
  actual_cost                NUMERIC(18,2),
  forecast_cost              NUMERIC(18,2),
  created_at                 TIMESTAMPTZ   NOT NULL DEFAULT now(),
  created_by_person_id       BIGINT        REFERENCES people (id),
  updated_at                 TIMESTAMPTZ   NOT NULL DEFAULT now(),
  updated_by_person_id       BIGINT        REFERENCES people (id),
  last_reviewed_at           TIMESTAMPTZ,
  last_reviewed_by_person_id BIGINT        REFERENCES people (id),
  FOREIGN KEY (type_list, type) REFERENCES master_data_items (list_key, code),
  FOREIGN KEY (priority_list, priority) REFERENCES master_data_items (list_key, code),
  FOREIGN KEY (status_list, status) REFERENCES master_data_items (list_key, code),
  FOREIGN KEY (health_list, health) REFERENCES master_data_items (list_key, code),
  FOREIGN KEY (confidentiality_list, confidentiality) REFERENCES master_data_items (list_key, code),
  FOREIGN KEY (current_phase_list, current_phase) REFERENCES master_data_items (list_key, code),
  FOREIGN KEY (currency_list, currency) REFERENCES master_data_items (list_key, code)
);

CREATE TABLE milestones (                         -- Project.milestones
  id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  project_id      BIGINT NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
  title           TEXT   NOT NULL,
  due_date        DATE   NOT NULL,
  completed_date  DATE,
  status          TEXT   NOT NULL,
  status_list     TEXT   NOT NULL GENERATED ALWAYS AS ('milestoneStatuses') STORED,
  FOREIGN KEY (status_list, status) REFERENCES master_data_items (list_key, code)
);

CREATE TABLE application_impacts (                -- Project.applicationImpacts
  id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  project_id       BIGINT NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
  application_id   BIGINT NOT NULL REFERENCES applications (id) ON DELETE CASCADE,
  impact_type      TEXT   NOT NULL,
  impact_type_list TEXT   NOT NULL GENERATED ALWAYS AS ('applicationImpactTypes') STORED,
  description      TEXT   NOT NULL DEFAULT '',
  UNIQUE (project_id, application_id, impact_type),
  FOREIGN KEY (impact_type_list, impact_type) REFERENCES master_data_items (list_key, code)
);

-- -----------------------------------------------------------------------------------------------------
-- Ownership shared by applications and projects (exactly one parent per row)
-- -----------------------------------------------------------------------------------------------------

CREATE TABLE role_assignments (                   -- Application.roles / Project.roles
  id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  application_id  BIGINT REFERENCES applications (id) ON DELETE CASCADE,
  project_id      BIGINT REFERENCES projects (id) ON DELETE CASCADE,
  person_id       BIGINT NOT NULL REFERENCES people (id) ON DELETE RESTRICT,
  role            TEXT   NOT NULL,
  role_list       TEXT   NOT NULL GENERATED ALWAYS AS ('stakeholderRoles') STORED,
  sort_order      INTEGER NOT NULL,
  CHECK (num_nonnulls(application_id, project_id) = 1),
  UNIQUE (application_id, project_id, person_id, role),
  FOREIGN KEY (role_list, role) REFERENCES master_data_items (list_key, code)
);

CREATE TABLE team_assignments (                   -- Application.teams / Project.teams
  id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  application_id  BIGINT REFERENCES applications (id) ON DELETE CASCADE,
  project_id      BIGINT REFERENCES projects (id) ON DELETE CASCADE,
  team_id         BIGINT NOT NULL REFERENCES teams (id) ON DELETE CASCADE,
  responsibility  TEXT   NOT NULL,
  responsibility_list TEXT NOT NULL GENERATED ALWAYS AS ('teamResponsibilities') STORED,
  CHECK (num_nonnulls(application_id, project_id) = 1),
  FOREIGN KEY (responsibility_list, responsibility) REFERENCES master_data_items (list_key, code)
);

CREATE TABLE documentation_links (                -- Application.documentation / Project.documentation
  id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  application_id  BIGINT REFERENCES applications (id) ON DELETE CASCADE,
  project_id      BIGINT REFERENCES projects (id) ON DELETE CASCADE,
  type            TEXT   NOT NULL,
  type_list       TEXT   NOT NULL GENERATED ALWAYS AS ('documentationLinkTypes') STORED,
  title           TEXT   NOT NULL,
  url             TEXT   NOT NULL CHECK (url ~ '^https?://'),
  description     TEXT,
  CHECK (num_nonnulls(application_id, project_id) = 1),
  FOREIGN KEY (type_list, type) REFERENCES master_data_items (list_key, code)
);

-- -----------------------------------------------------------------------------------------------------
-- Connections
-- -----------------------------------------------------------------------------------------------------

CREATE TABLE dependencies (                       -- source depends on target
  id                         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  source_application_id      BIGINT      NOT NULL REFERENCES applications (id) ON DELETE CASCADE,
  target_application_id      BIGINT      NOT NULL REFERENCES applications (id) ON DELETE CASCADE,
  type                       TEXT        NOT NULL,
  type_list                  TEXT        NOT NULL GENERATED ALWAYS AS ('dependencyTypes') STORED,
  criticality                TEXT        NOT NULL,
  criticality_list           TEXT        NOT NULL GENERATED ALWAYS AS ('criticalities') STORED,
  description                TEXT        NOT NULL DEFAULT '',
  created_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by_person_id       BIGINT      REFERENCES people (id),
  updated_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by_person_id       BIGINT      REFERENCES people (id),
  last_reviewed_at           TIMESTAMPTZ,
  last_reviewed_by_person_id BIGINT      REFERENCES people (id),
  CHECK (source_application_id <> target_application_id),
  UNIQUE (source_application_id, target_application_id, type),
  FOREIGN KEY (type_list, type) REFERENCES master_data_items (list_key, code),
  FOREIGN KEY (criticality_list, criticality) REFERENCES master_data_items (list_key, code)
);

CREATE TABLE integrations (
  id                         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name                       TEXT        NOT NULL,
  type                       TEXT        NOT NULL,
  type_list                  TEXT        NOT NULL GENERATED ALWAYS AS ('integrationTypes') STORED,
  from_application_id        BIGINT      NOT NULL REFERENCES applications (id) ON DELETE CASCADE,
  to_application_id          BIGINT      REFERENCES applications (id) ON DELETE CASCADE,
  external_party_name        TEXT,
  frequency                  TEXT        NOT NULL,
  frequency_list             TEXT        NOT NULL GENERATED ALWAYS AS ('integrationFrequencies') STORED,
  data_exchanged             TEXT        NOT NULL DEFAULT '',
  description                TEXT        NOT NULL DEFAULT '',
  created_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by_person_id       BIGINT      REFERENCES people (id),
  updated_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by_person_id       BIGINT      REFERENCES people (id),
  last_reviewed_at           TIMESTAMPTZ,
  last_reviewed_by_person_id BIGINT      REFERENCES people (id),
  CHECK (num_nonnulls(to_application_id, external_party_name) = 1),
  FOREIGN KEY (type_list, type) REFERENCES master_data_items (list_key, code),
  FOREIGN KEY (frequency_list, frequency) REFERENCES master_data_items (list_key, code)
);

-- -----------------------------------------------------------------------------------------------------
-- Operational knowledge
-- -----------------------------------------------------------------------------------------------------

CREATE TABLE risks (
  id                         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title                      TEXT        NOT NULL,
  description                TEXT        NOT NULL DEFAULT '',
  category                   TEXT        NOT NULL,
  category_list              TEXT        NOT NULL GENERATED ALWAYS AS ('riskCategories') STORED,
  probability                TEXT        NOT NULL CHECK (probability IN ('low', 'medium', 'high')),
  impact                     TEXT        NOT NULL CHECK (impact IN ('low', 'medium', 'high')),
  severity                   TEXT        NOT NULL,
  severity_list              TEXT        NOT NULL GENERATED ALWAYS AS ('criticalities') STORED,
  status                     TEXT        NOT NULL,
  status_list                TEXT        NOT NULL GENERATED ALWAYS AS ('riskStatuses') STORED,
  owner_person_id            BIGINT      REFERENCES people (id) ON DELETE RESTRICT,
  mitigation_plan            TEXT        NOT NULL DEFAULT '',
  due_date                   DATE,
  created_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by_person_id       BIGINT      REFERENCES people (id),
  updated_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by_person_id       BIGINT      REFERENCES people (id),
  last_reviewed_at           TIMESTAMPTZ,
  last_reviewed_by_person_id BIGINT      REFERENCES people (id),
  FOREIGN KEY (category_list, category) REFERENCES master_data_items (list_key, code),
  FOREIGN KEY (severity_list, severity) REFERENCES master_data_items (list_key, code),
  FOREIGN KEY (status_list, status) REFERENCES master_data_items (list_key, code)
);

CREATE TABLE escalations (
  id                         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title                      TEXT        NOT NULL,
  description                TEXT        NOT NULL DEFAULT '',
  severity                   TEXT        NOT NULL,
  severity_list              TEXT        NOT NULL GENERATED ALWAYS AS ('criticalities') STORED,
  status                     TEXT        NOT NULL,
  status_list                TEXT        NOT NULL GENERATED ALWAYS AS ('escalationStatuses') STORED,
  owner_person_id            BIGINT      REFERENCES people (id) ON DELETE RESTRICT,
  responsible_team_id        BIGINT      REFERENCES teams (id) ON DELETE SET NULL,
  raised_by_person_id        BIGINT      NOT NULL REFERENCES people (id) ON DELETE RESTRICT,
  raised_at                  TIMESTAMPTZ NOT NULL,
  target_resolution_date     DATE,
  resolution                 TEXT,
  resolved_on                DATE,        -- set when resolved/closed; drives resolution-time reports
  CHECK (resolved_on IS NULL OR resolved_on >= raised_at::date),
  created_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by_person_id       BIGINT      REFERENCES people (id),
  updated_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by_person_id       BIGINT      REFERENCES people (id),
  last_reviewed_at           TIMESTAMPTZ,
  last_reviewed_by_person_id BIGINT      REFERENCES people (id),
  FOREIGN KEY (severity_list, severity) REFERENCES master_data_items (list_key, code),
  FOREIGN KEY (status_list, status) REFERENCES master_data_items (list_key, code)
);

CREATE TABLE decisions (
  id                         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title                      TEXT        NOT NULL,
  context                    TEXT        NOT NULL,
  decision                   TEXT        NOT NULL,
  rationale                  TEXT        NOT NULL DEFAULT '',
  alternatives               TEXT[]      NOT NULL DEFAULT '{}',
  consequences               TEXT        NOT NULL DEFAULT '',
  decision_date              DATE        NOT NULL,
  status                     TEXT        NOT NULL,
  status_list                TEXT        NOT NULL GENERATED ALWAYS AS ('decisionStatuses') STORED,
  created_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by_person_id       BIGINT      REFERENCES people (id),
  updated_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by_person_id       BIGINT      REFERENCES people (id),
  last_reviewed_at           TIMESTAMPTZ,
  last_reviewed_by_person_id BIGINT      REFERENCES people (id),
  FOREIGN KEY (status_list, status) REFERENCES master_data_items (list_key, code)
);

CREATE TABLE decision_makers (                    -- Decision.decidedByIds
  id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  decision_id  BIGINT NOT NULL REFERENCES decisions (id) ON DELETE CASCADE,
  person_id    BIGINT NOT NULL REFERENCES people (id) ON DELETE RESTRICT,
  UNIQUE (decision_id, person_id)
);

-- relatedApplicationIds / relatedProjectIds of risks, escalations and decisions
CREATE TABLE risk_applications (
  id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  risk_id         BIGINT NOT NULL REFERENCES risks (id) ON DELETE CASCADE,
  application_id  BIGINT NOT NULL REFERENCES applications (id) ON DELETE CASCADE,
  UNIQUE (risk_id, application_id)
);
CREATE TABLE risk_projects (
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  risk_id     BIGINT NOT NULL REFERENCES risks (id) ON DELETE CASCADE,
  project_id  BIGINT NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
  UNIQUE (risk_id, project_id)
);
CREATE TABLE escalation_applications (
  id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  escalation_id   BIGINT NOT NULL REFERENCES escalations (id) ON DELETE CASCADE,
  application_id  BIGINT NOT NULL REFERENCES applications (id) ON DELETE CASCADE,
  UNIQUE (escalation_id, application_id)
);
CREATE TABLE escalation_projects (
  id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  escalation_id  BIGINT NOT NULL REFERENCES escalations (id) ON DELETE CASCADE,
  project_id     BIGINT NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
  UNIQUE (escalation_id, project_id)
);
CREATE TABLE decision_applications (
  id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  decision_id     BIGINT NOT NULL REFERENCES decisions (id) ON DELETE CASCADE,
  application_id  BIGINT NOT NULL REFERENCES applications (id) ON DELETE CASCADE,
  UNIQUE (decision_id, application_id)
);
CREATE TABLE decision_projects (
  id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  decision_id  BIGINT NOT NULL REFERENCES decisions (id) ON DELETE CASCADE,
  project_id   BIGINT NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
  UNIQUE (decision_id, project_id)
);

-- -----------------------------------------------------------------------------------------------------
-- Incident runbooks ("Sorun anında") — one per application; never credentials
-- -----------------------------------------------------------------------------------------------------

CREATE TABLE application_runbooks (               -- Runbook
  id                         BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  application_id             BIGINT      NOT NULL UNIQUE REFERENCES applications (id) ON DELETE CASCADE,
  summary                    TEXT        NOT NULL DEFAULT '',
  last_verified_on           DATE,
  created_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by_person_id       BIGINT      REFERENCES people (id),
  updated_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by_person_id       BIGINT      REFERENCES people (id),
  last_reviewed_at           TIMESTAMPTZ,
  last_reviewed_by_person_id BIGINT      REFERENCES people (id)
);

CREATE TABLE runbook_scenarios (                  -- Runbook.scenarios (known problems)
  id          BIGINT  GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  runbook_id  BIGINT  NOT NULL REFERENCES application_runbooks (id) ON DELETE CASCADE,
  position    INTEGER NOT NULL,
  title       VARCHAR(160) NOT NULL,
  symptoms    TEXT    NOT NULL DEFAULT '',
  UNIQUE (runbook_id, position)
);

-- Ordered steps: first response (scenario_id NULL) or the resolution of one known problem.
CREATE TABLE runbook_steps (                      -- Runbook.firstResponse / RunbookScenario.steps
  id           BIGINT  GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  runbook_id   BIGINT  NOT NULL REFERENCES application_runbooks (id) ON DELETE CASCADE,
  scenario_id  BIGINT  REFERENCES runbook_scenarios (id) ON DELETE CASCADE,
  position     INTEGER NOT NULL,
  text         TEXT    NOT NULL CHECK (text <> ''),
  UNIQUE NULLS NOT DISTINCT (runbook_id, scenario_id, position)
);

CREATE TABLE runbook_links (                      -- Runbook.links (addresses to check)
  id          BIGINT  GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  runbook_id  BIGINT  NOT NULL REFERENCES application_runbooks (id) ON DELETE CASCADE,
  position    INTEGER NOT NULL,
  type        TEXT    NOT NULL,
  type_list   TEXT    NOT NULL GENERATED ALWAYS AS ('runbookLinkTypes') STORED,
  label       VARCHAR(120) NOT NULL,
  url         TEXT    NOT NULL CHECK (url ~ '^https?://'),
  note        VARCHAR(300) NOT NULL DEFAULT '',
  UNIQUE (runbook_id, position),
  FOREIGN KEY (type_list, type) REFERENCES master_data_items (list_key, code)
);

CREATE TABLE runbook_contacts (                   -- Runbook.contacts, in escalation order
  id          BIGINT  GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  runbook_id  BIGINT  NOT NULL REFERENCES application_runbooks (id) ON DELETE CASCADE,
  position    INTEGER NOT NULL,
  label       VARCHAR(120) NOT NULL,
  person_id   BIGINT  REFERENCES people (id) ON DELETE RESTRICT,
  team_id     BIGINT  REFERENCES teams (id) ON DELETE CASCADE,
  channel     VARCHAR(200) NOT NULL DEFAULT '',
  "when"      VARCHAR(200) NOT NULL DEFAULT '',
  UNIQUE (runbook_id, position),
  CHECK (person_id IS NOT NULL OR team_id IS NOT NULL OR channel <> '')
);

-- -----------------------------------------------------------------------------------------------------
-- Leave management
-- -----------------------------------------------------------------------------------------------------

-- Lets the exclusion constraint below combine `=` on person_id with `&&` on the date range.
CREATE EXTENSION IF NOT EXISTS btree_gist;

CREATE TABLE leave_records (                      -- LeaveRecord
  id                         BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  person_id                  BIGINT      NOT NULL REFERENCES people (id) ON DELETE CASCADE,
  type                       TEXT        NOT NULL,
  type_list                  TEXT        NOT NULL GENERATED ALWAYS AS ('leaveTypes') STORED,
  start_date                 DATE        NOT NULL,
  end_date                   DATE        NOT NULL,   -- inclusive
  note                       VARCHAR(200) NOT NULL DEFAULT '',
  created_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by_person_id       BIGINT      REFERENCES people (id),
  updated_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by_person_id       BIGINT      REFERENCES people (id),
  last_reviewed_at           TIMESTAMPTZ,
  last_reviewed_by_person_id BIGINT      REFERENCES people (id),
  CHECK (end_date >= start_date),
  FOREIGN KEY (type_list, type) REFERENCES master_data_items (list_key, code),
  -- One person cannot have two leaves on the same day (the mock repository enforces the same rule).
  EXCLUDE USING gist (person_id WITH =, daterange(start_date, end_date, '[]') WITH &&)
);

-- -----------------------------------------------------------------------------------------------------
-- Resource planning
-- -----------------------------------------------------------------------------------------------------

-- A person planned onto a project for a period at a share of their time. Overlapping allocations
-- on different projects are parallel work (allowed, and what the planner shows); the same person
-- cannot be booked twice onto one project for overlapping days.
CREATE TABLE resource_allocations (               -- Allocation
  id                         BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  person_id                  BIGINT      NOT NULL REFERENCES people (id) ON DELETE RESTRICT,
  project_id                 BIGINT      NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
  role                       TEXT        NOT NULL,
  role_list                  TEXT        NOT NULL GENERATED ALWAYS AS ('stakeholderRoles') STORED,
  start_date                 DATE        NOT NULL,
  end_date                   DATE        NOT NULL,   -- inclusive
  percent                    SMALLINT    NOT NULL CHECK (percent BETWEEN 5 AND 100 AND percent % 5 = 0),
  note                       VARCHAR(200) NOT NULL DEFAULT '',
  created_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by_person_id       BIGINT      REFERENCES people (id),
  updated_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by_person_id       BIGINT      REFERENCES people (id),
  last_reviewed_at           TIMESTAMPTZ,
  last_reviewed_by_person_id BIGINT      REFERENCES people (id),
  CHECK (end_date >= start_date),
  FOREIGN KEY (role_list, role) REFERENCES master_data_items (list_key, code),
  EXCLUDE USING gist (
    person_id WITH =,
    project_id WITH =,
    daterange(start_date, end_date, '[]') WITH &&
  )
);

-- -----------------------------------------------------------------------------------------------------
-- Demand management (requests from business units, assessed and scheduled by the portfolio office)
-- -----------------------------------------------------------------------------------------------------

-- A request for change. The requester's part (what and why) and the portfolio office's assessment
-- (WSJF scores, priority, plan, decision) live on one row; status changes are in `demand_events`.
CREATE TABLE demands (                            -- Demand
  id                         BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code                       VARCHAR(20) NOT NULL UNIQUE GENERATED ALWAYS AS ('TLP-' || lpad(id::text, 4, '0')) STORED,
  title                      VARCHAR(200) NOT NULL CHECK (title <> ''),
  type                       TEXT        NOT NULL,
  type_list                  TEXT        NOT NULL GENERATED ALWAYS AS ('demandTypes') STORED,
  business_unit_id           BIGINT      NOT NULL REFERENCES business_units (id) ON DELETE RESTRICT,
  requester_person_id        BIGINT      NOT NULL REFERENCES people (id) ON DELETE RESTRICT,
  sponsor_person_id          BIGINT      REFERENCES people (id) ON DELETE RESTRICT,
  problem                    VARCHAR(4000) NOT NULL CHECK (problem <> ''),
  proposed_solution          VARCHAR(4000) NOT NULL DEFAULT '',
  expected_benefits          VARCHAR(4000) NOT NULL CHECK (expected_benefits <> ''),
  urgency                    TEXT        NOT NULL,
  urgency_list               TEXT        NOT NULL GENERATED ALWAYS AS ('criticalities') STORED,
  desired_date               DATE,
  deadline_reason            VARCHAR(500) NOT NULL DEFAULT '',
  regulatory                 BOOLEAN     NOT NULL DEFAULT false,
  affected_users             INTEGER     CHECK (affected_users >= 0),
  estimated_budget           NUMERIC(14, 2) CHECK (estimated_budget >= 0),
  currency                   TEXT        NOT NULL DEFAULT 'TRY',
  currency_list              TEXT        NOT NULL GENERATED ALWAYS AS ('currencies') STORED,
  status                     TEXT        NOT NULL DEFAULT 'submitted',
  status_list                TEXT        NOT NULL GENERATED ALWAYS AS ('demandStatuses') STORED,
  submitted_at               TIMESTAMPTZ NOT NULL DEFAULT now(),
  -- Assessment (1 = lowest … 5 = highest; effort 1 = weeks … 5 = a year or more)
  business_value             SMALLINT    CHECK (business_value BETWEEN 1 AND 5),
  strategic_fit              SMALLINT    CHECK (strategic_fit BETWEEN 1 AND 5),
  time_criticality           SMALLINT    CHECK (time_criticality BETWEEN 1 AND 5),
  risk_reduction             SMALLINT    CHECK (risk_reduction BETWEEN 1 AND 5),
  effort                     SMALLINT    CHECK (effort BETWEEN 1 AND 5),
  priority                   TEXT,
  priority_list              TEXT        NOT NULL GENERATED ALWAYS AS ('demandPriorities') STORED,
  assessor_person_id         BIGINT      REFERENCES people (id) ON DELETE SET NULL,
  planned_start              DATE,
  planned_end                DATE,
  decision_note              VARCHAR(2000) NOT NULL DEFAULT '',
  project_id                 BIGINT      REFERENCES projects (id) ON DELETE SET NULL,
  created_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by_person_id       BIGINT      REFERENCES people (id),
  updated_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by_person_id       BIGINT      REFERENCES people (id),
  last_reviewed_at           TIMESTAMPTZ,
  last_reviewed_by_person_id BIGINT      REFERENCES people (id),
  FOREIGN KEY (type_list, type) REFERENCES master_data_items (list_key, code),
  FOREIGN KEY (urgency_list, urgency) REFERENCES master_data_items (list_key, code),
  FOREIGN KEY (currency_list, currency) REFERENCES master_data_items (list_key, code),
  FOREIGN KEY (status_list, status) REFERENCES master_data_items (list_key, code),
  FOREIGN KEY (priority_list, priority) REFERENCES master_data_items (list_key, code),
  CHECK (planned_end >= planned_start),
  -- The workflow rules the repository enforces (system codes of `demandStatuses`).
  CHECK (status NOT IN ('rejected', 'needs-info') OR decision_note <> ''),
  CHECK (status NOT IN ('approved', 'scheduled', 'converted') OR priority IS NOT NULL),
  CHECK (status NOT IN ('scheduled', 'converted') OR (planned_start IS NOT NULL AND planned_end IS NOT NULL)),
  CHECK (status <> 'converted' OR project_id IS NOT NULL)
);

CREATE TABLE demand_benefit_types (
  demand_id  BIGINT NOT NULL REFERENCES demands (id) ON DELETE CASCADE,
  code       TEXT   NOT NULL,
  code_list  TEXT   NOT NULL GENERATED ALWAYS AS ('demandBenefitTypes') STORED,
  PRIMARY KEY (demand_id, code),
  FOREIGN KEY (code_list, code) REFERENCES master_data_items (list_key, code)
);

CREATE TABLE demand_applications (
  demand_id      BIGINT NOT NULL REFERENCES demands (id) ON DELETE CASCADE,
  application_id BIGINT NOT NULL REFERENCES applications (id) ON DELETE CASCADE,
  PRIMARY KEY (demand_id, application_id)
);

-- Status history; written by the server with each status change, never edited.
CREATE TABLE demand_events (                      -- DemandEvent
  id               BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  demand_id        BIGINT      NOT NULL REFERENCES demands (id) ON DELETE CASCADE,
  at               TIMESTAMPTZ NOT NULL DEFAULT now(),
  by_person_id     BIGINT      REFERENCES people (id) ON DELETE SET NULL,
  status           TEXT        NOT NULL,
  status_list      TEXT        NOT NULL GENERATED ALWAYS AS ('demandStatuses') STORED,
  note             VARCHAR(2000) NOT NULL DEFAULT '',
  FOREIGN KEY (status_list, status) REFERENCES master_data_items (list_key, code)
);

-- -----------------------------------------------------------------------------------------------------
-- Attachments (files on records) — bytes in object storage under the row id, metadata here
-- -----------------------------------------------------------------------------------------------------

-- One nullable foreign key per owner type keeps referential integrity (the domain's
-- `owner: { type, id }`); exactly one is set. Files go with their record (ON DELETE CASCADE);
-- the object-storage bytes of deleted rows are swept by a background job.
CREATE TABLE attachments (                        -- Attachment
  id                         BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  application_id             BIGINT      REFERENCES applications (id) ON DELETE CASCADE,
  project_id                 BIGINT      REFERENCES projects (id) ON DELETE CASCADE,
  team_id                    BIGINT      REFERENCES teams (id) ON DELETE CASCADE,
  technology_id              BIGINT      REFERENCES technologies (id) ON DELETE CASCADE,
  risk_id                    BIGINT      REFERENCES risks (id) ON DELETE CASCADE,
  escalation_id              BIGINT      REFERENCES escalations (id) ON DELETE CASCADE,
  decision_id                BIGINT      REFERENCES decisions (id) ON DELETE CASCADE,
  demand_id                  BIGINT      REFERENCES demands (id) ON DELETE CASCADE,
  document_type              TEXT        NOT NULL,
  document_type_list         TEXT        NOT NULL GENERATED ALWAYS AS ('documentTypes') STORED,
  file_name                  VARCHAR(200) NOT NULL CHECK (file_name <> '' AND file_name !~ '[/\\]'),
  content_type               VARCHAR(150) NOT NULL,
  size_bytes                 BIGINT      NOT NULL CHECK (size_bytes > 0 AND size_bytes <= 20971520),
  description                VARCHAR(300) NOT NULL DEFAULT '',
  uploaded_at                TIMESTAMPTZ NOT NULL DEFAULT now(),
  uploaded_by_person_id      BIGINT      REFERENCES people (id),
  created_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by_person_id       BIGINT      REFERENCES people (id),
  updated_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by_person_id       BIGINT      REFERENCES people (id),
  last_reviewed_at           TIMESTAMPTZ,
  last_reviewed_by_person_id BIGINT      REFERENCES people (id),
  CHECK (num_nonnulls(application_id, project_id, team_id, technology_id, risk_id, escalation_id, decision_id, demand_id) = 1),
  -- Executables, scripts, HTML and SVG are refused (the application validates the same list).
  CHECK (lower(file_name) ~ '\.(pdf|docx?|odt|rtf|txt|md|xlsx?|ods|csv|pptx?|odp|png|jpe?g|gif|webp|vsdx|drawio|zip)$'),
  FOREIGN KEY (document_type_list, document_type) REFERENCES master_data_items (list_key, code)
);

